import { createAccessControl } from "better-auth/plugins/access"
import {
  adminAc,
  defaultStatements,
  memberAc,
  ownerAc,
} from "better-auth/plugins/organization/access"

import { moduleGrants, moduleStatements } from "@/modules/_generated/permissions"

/**
 * The app's permission statements — the EXTENSION POINT for RBAC (outside the
 * read-only server/auth/** zone on purpose). Add the app's resources here:
 *
 *   const statement = { ...defaultStatements, project: ["create", "update", "delete"] } as const
 *
 * then grant them in the roles below. Modules do NOT edit this file: they
 * declare `permissions` in their own folder and `pnpm modules:sync` merges them
 * through modules/_generated/permissions.ts. Roles can also be created at runtime in
 * the "organizationRole" table (dynamic access control); those are merged on
 * top of these static ones.
 */
export const statement = { ...defaultStatements, ...moduleStatements } as const

export const ac = createAccessControl(statement)

export const roles = {
  owner: ac.newRole({ ...ownerAc.statements, ...moduleGrants.owner }),
  admin: ac.newRole({ ...adminAc.statements, ...moduleGrants.admin }),
  member: ac.newRole({ ...memberAc.statements, ...moduleGrants.member }),
}
